 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump(300);((System.Threading.Timer)Get(pet,"assistantTimer")).Change(System.Threading.Timeout.Infinite,System.Threading.Timeout.Infinite);Pump(100);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("任务栏外观");Pump();var primary=Find<Button>(w,b=>Convert.ToString(b.Content)=="应用并保存任务栏外观");var secondary=Find<Button>(w,b=>Convert.ToString(b.Content)=="重新载入已保存设置");Check(Convert.ToString(primary.Tag)=="primary"&&primary.MinHeight>=44,"apply action has distinct primary role and shape");var surface=(Border)primary.Template.FindName("Surface",primary);var secondarySurface=(Border)secondary.Template.FindName("Surface",secondary);Check(((SolidColorBrush)surface.Background).Color!=((SolidColorBrush)secondarySurface.Background).Color,"primary action uses a contrasting filled surface");Check(((SolidColorBrush)primary.Foreground).Color.R>240,"primary label retains white contrast in A theme");w.SetTheme("b",false);Pump();Check(((SolidColorBrush)primary.Foreground).Color.R>240&&((SolidColorBrush)surface.Background).Color!=((SolidColorBrush)secondarySurface.Background).Color,"primary remains contrasted after B theme switch");w.SetTheme("a",false);Pump();Shot(w,Path.Combine(args[0],"primary-actions-native.png"));Click(w,"单位与占用图");var quotaMode=Named<ComboBox>(w,"Codex 额度显示");Check(quotaMode!=null&&quotaMode.SelectedIndex==0,"quota display default available in settings");quotaMode.SelectedIndex=3;Pump();Check(assistant.Config.Monitor.Appearance.QuotaDisplay=="remaining-reset","quota choice stays draft until applied");Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.QuotaDisplay=="query","quota display applies and saves");Shot(w,Path.Combine(args[0],"quota-display-settings.png"));Click(w,"显示项目");var gpu=Named<CheckBox>(w,"显示项目-gpu");gpu.IsChecked=true;gpu.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));var source=Named<Border>(w,"拖动排序-gpu");var target=Named<Border>(w,"拖动排序-cpu");Check(source!=null&&target!=null,"visible drag grips available for resource rows");var frame=(Border)((FrameworkElement)((FrameworkElement)target.Parent).Parent).Parent;var data=(IDataObject)Call(w,"TaskbarDragData",source.Tag);var over=DropArgs(data,frame,DragDrop.PreviewDragOverEvent,2);frame.RaiseEvent(over);Check(over.Effects==DragDropEffects.Move,"valid internal drag accepted by row");Shot(w,Path.Combine(args[0],"drag-order-native.png"));frame.RaiseEvent(DropArgs(data,frame,DragDrop.PreviewDropEvent,2));Pump();var draft=(MonitorConfig)Get(w,"taskbarDraft");Check(draft.TaskbarItems.IndexOf("gpu")<draft.TaskbarItems.IndexOf("cpu"),"drop before target updates live preview order");Check(!assistant.Config.Monitor.TaskbarItems.Contains("gpu"),"drag remains a preview until applied");var before=String.Join(",",draft.TaskbarItems);var external=DropArgs(new DataObject("Conan.TaskbarOrder","wrong-token"),frame,DragDrop.PreviewDropEvent,2);frame.RaiseEvent(external);Check(external.Effects==DragDropEffects.None&&String.Join(",",draft.TaskbarItems)==before,"unrelated drop cannot reorder resources");Click(w,"应用并保存任务栏外观");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(restored.Config.Monitor.TaskbarItems.IndexOf("gpu")<restored.Config.Monitor.TaskbarItems.IndexOf("cpu"),"drag order survives save and runtime restart");restored.Telemetry.Dispose();var down=Named<Button>(w,"下移-gpu");down.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(draft.TaskbarItems.IndexOf("gpu")>draft.TaskbarItems.IndexOf("cpu"),"arrow buttons still provide precise fallback ordering");
 Click(w,"单位与占用图");Named<ComboBox>(w,"资源百分比小数位").SelectedIndex=2;Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.PercentDecimals==2,"resource precision control persists");
 var card=new MonitorCard(new MonitorConfig(),null){Owner=pet};card.Show();card.Update(new SystemSample{Utc=DateTime.UtcNow,Cpu=20,MemoryUsed=8,MemoryTotal=32,Gpu=10});card.Update(null);var labels=(Dictionary<string,TextBlock>)Get(card,"labels");Check(labels.Values.All(t=>t.Text=="—"),"details card clears stale resources on sample failure");card.Update(new SystemSample{Utc=DateTime.UtcNow,Cpu=33,MemoryUsed=8,MemoryTotal=32,Gpu=12});Check(labels["cpu"].Text!="—","details card resumes new resource values after failure");card.Close();

 w.ShowPage("启动与窗口");Pump();Check(Find<CheckBox>(w,x=>Convert.ToString(x.Content)=="登录 Windows 时自动启动柯南")!=null,"startup manual switch visible without enabling it");Check(Find<Button>(w,x=>Convert.ToString(x.Content)=="创建 / 更新桌面快捷方式")!=null,"desktop shortcut explicit action available");Shot(w,Path.Combine(args[0],"startup-settings-native.png"));Click(w,"任务栏外观与排版 →");Check(Convert.ToString(Get(w,"page"))=="任务栏外观","central window page opens detailed taskbar settings");
 var moment=DateTime.UtcNow;var q=new CodexQuotaSnapshot{CheckedUtc=moment,AccountKey="test",Windows=new List<CodexQuotaWindow>{new CodexQuotaWindow{Minutes=300,Remaining=45,ResetUtc=moment.AddHours(2)},new CodexQuotaWindow{Minutes=10080,Remaining=60,ResetUtc=moment.AddDays(3)}}};assistant.Config.Monitor.Quota.ResetHistory.Add(new CodexQuotaReset{Minutes=10080,Kind="early",ObservedUtc=moment,PreviousCheckedUtc=moment.AddMinutes(-1),PreviousRemaining=20,Remaining=100,PreviousResetUtc=moment.AddDays(1),NewResetUtc=moment.AddDays(7)});w.ShowQuotaPage();w.Refresh(new AssistantSnapshot{Sample=new SystemSample{Utc=moment,Quota=q},Watches=new WatchedProcess[0],Notices=new string[0]});Pump();Check(((TextBlock)Get(w,"quotaCountdown")).Text.Contains("五小时重置")&&((TextBlock)Get(w,"quotaCountdown")).Text.Contains("周额度重置"),"both reset countdowns shown on quota page");Check(((TextBlock)Get(w,"quotaHistory")).Text.Contains("疑似重置")&&((TextBlock)Get(w,"quotaHistory")).Text.Contains("首次检测"),"history distinguishes suspected reset and detection time");w.ShowPage("侦探备忘录");Click(w,"额度与重置");Check(Find<CheckBox>(w,x=>Convert.ToString(x.Content)=="额度即将重置时提醒")!=null,"reset reminder manual switch available");foreach(var exp in Descendants(w).OfType<Expander>())exp.IsExpanded=true;Pump();Shot(w,Path.Combine(args[0],"quota-countdown-native.png"));Check(Find<Button>(w,x=>Convert.ToString(x.Content)=="授权并连接额度服务…")!=null,"quota connection requires explicit authorization control");Check(Find<Button>(w,x=>Convert.ToString(x.Content)=="撤销额度程序授权")!=null,"quota grant can be revoked from settings");

 }catch(Exception e){failures++;Console.WriteLine(e);}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"v520-ui-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+",\"physical_mouse_drag_verified\":false}");return failures==0?0:1;}
